import { Pool } from "pg";

export interface ReminderJob {
  id: string;
  appointmentId: string;
  channel: "sms" | "email";
}

export class ReminderRepo {
  constructor(private pool: Pool) {}

  async claimNext(workerId: string): Promise<ReminderJob | null> {
    const { rows } = await this.pool.query(
      `UPDATE reminder_jobs SET locked_by = $1, locked_until = now() + interval '2 minutes'
         WHERE id = (
           SELECT id FROM reminder_jobs
            WHERE status = 'pending' AND send_at <= now()
              AND (locked_until IS NULL OR locked_until < now())
            ORDER BY send_at
            FOR UPDATE SKIP LOCKED
            LIMIT 1)
       RETURNING id, appointment_id AS "appointmentId", channel`,
      [workerId],
    );
    return rows[0] ?? null;
  }

  async loadAppointment(id: string) {
    const { rows } = await this.pool.query(
      `SELECT a.starts_at, p.phone, p.email, c.name AS clinic
         FROM appointments a JOIN patients p ON p.id = a.patient_id JOIN clinics c ON c.id = a.clinic_id
        WHERE a.id = $1 AND a.status = 'booked'`,
      [id],
    );
    return rows[0] ?? null;
  }

  async complete(jobId: string, status: "sent" | "skipped"): Promise<void> {
    await this.pool.query(
      `UPDATE reminder_jobs SET status = $2, locked_by = NULL, locked_until = NULL WHERE id = $1`,
      [jobId, status],
    );
  }
}

import { Pool } from "pg";
import { ReminderRepo, ReminderJob } from "./reminderRepo";

export interface Notifier {
  send(channel: "sms" | "email", to: string, text: string): Promise<void>;
}

const IDLE_POLL_MS = 1_000;
const DRAIN_TIMEOUT_MS = 25_000;

export class ReminderWorker {
  private stopping = false;
  private inFlight = new Set<Promise<void>>();
  private loopDone: Promise<void> | null = null;

  constructor(
    private pool: Pool,
    private repo: ReminderRepo,
    private notifier: Notifier,
    private workerId: string,
    private concurrency = 4,
  ) {}

  start(): void {
    this.loopDone = this.loop();
  }

  private async loop(): Promise<void> {
    while (!this.stopping) {
      if (this.inFlight.size >= this.concurrency) {
        await Promise.race(this.inFlight);
        continue;
      }
      const job = await this.repo.claimNext(this.workerId);
      if (!job) {
        await new Promise((r) => setTimeout(r, IDLE_POLL_MS));
        continue;
      }
      void this.track(job);
    }
  }

  private async track(job: ReminderJob): Promise<void> {
    const appt = await this.repo.loadAppointment(job.appointmentId);
    const p = this.process(job, appt).finally(() => this.inFlight.delete(p));
    this.inFlight.add(p);
    await p;
  }

  private async process(job: ReminderJob, appt: any): Promise<void> {
    try {
      if (!appt) {
        await this.repo.complete(job.id, "skipped");
        return;
      }
      const to = job.channel === "sms" ? appt.phone : appt.email;
      const when = new Date(appt.starts_at).toLocaleString("en-US");
      await this.notifier.send(job.channel, to, `Reminder: your appointment at ${appt.clinic} is on ${when}.`);
      await this.repo.complete(job.id, "sent");
    } catch (err) {
      console.error("reminder failed; lease will expire and job will be retried", job.id, err);
    }
  }

  async shutdown(): Promise<void> {
    this.stopping = true;
    await this.loopDone;
    const drained = Promise.allSettled([...this.inFlight]).then(() => true);
    const timedOut = new Promise<boolean>((r) => setTimeout(() => r(false), DRAIN_TIMEOUT_MS).unref());
    const ok = await Promise.race([drained, timedOut]);
    if (!ok) console.warn(`shutdown: ${this.inFlight.size} reminders still running, leases will expire`);
    await this.pool.end();
  }
}

import { Pool } from "pg";
import os from "os";
import { ReminderRepo } from "./reminderRepo";
import { ReminderWorker, Notifier } from "./reminderWorker";

export function run(notifier: Notifier) {
  const pool = new Pool({ connectionString: process.env.DATABASE_URL, max: 8 });
  const worker = new ReminderWorker(pool, new ReminderRepo(pool), notifier, `${os.hostname()}:${process.pid}`);
  worker.start();

  process.once("SIGTERM", async () => {
    await worker.shutdown();
    process.exit(0);
  });
}

